package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.jobs.VersionValidityService.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

class VersionValidityJdbcStoreTest {
    VersionValidityLedgerServiceTest base;ResultJdbcStoreTest fixture;VersionValidityJdbcStore store;VersionValidityService service;ContentReviewEvidenceService audit;
    @BeforeEach void setup(){base=new VersionValidityLedgerServiceTest();base.setup();install();}
    void install(){fixture=base.fixture;audit=new ContentReviewEvidenceService(fixture.source,base.contents,base.versions,fixture.clock,"fictional-owner");restart(null);}
    void restart(VersionValidityJdbcStore.DisplayCommand display){base.restart();store=new VersionValidityJdbcStore(base.ledger,new JdbcValidityPropagation(fixture.source),base.versions,base.contents,base.writer,fixture.clock,"fictional-owner",display);service=new VersionValidityService(fixture.writes,store);}
    void review(String kind,String id,String operation,String key){long revision=base.contents.reviewSnapshot(kind,id).orElseThrow().revision();var provider=new ReviewPublicationJdbcStore(new ReviewPublicationJdbcStore.Command(operation,kind,id,revision,null,"Fictional reviewed qualification"),base.writer,base.contents,audit,base.versions,base.ledger);var review=new ReviewPublicationService(fixture.writes,provider);if(operation.equals("approve"))review.approve(kind,id,revision,fixture.action(key));else review.publish(kind,id,revision,fixture.action(key));}
    void publish(){review("report","fictional-report","approve","fictional-approve");review("report","fictional-report","publish","fictional-publish");}
    Result invalidate(JsonNode target,long expected,String key){return service.change(base.command(target,expected,Action.INVALIDATE,null),fixture.action(key));}
    int drain(String prefix){int count=0;while(service.propagateNext(fixture.action(prefix+count))){restart(null);if(++count>1000)fail("propagation failed to terminate");}return count;}
    JsonNode seed(String suffix,List<JsonNode> references){
        String owner="fictional-owner-"+suffix,id="fictional-agent-"+suffix,entity="fictional-entity-"+suffix;
        var context=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(FrozenApplicationContextTest.context(Stage.AGENT_ANALYSIS));((tools.jackson.databind.node.ObjectNode)context.get("target_content")).put("id",id);context.put("target_entity_id",entity);var refs=context.putArray("reference_targets");references.forEach(refs::add);
        var ctx=FrozenApplicationContext.fromJson(context);var evidence=new Evidence("fictional-material","analysis",LocalDate.of(2026,1,1),Instant.parse("2026-01-01T20:00:00Z"),"a".repeat(64),"{\"text\":\"Fictional bounded material\"}",true,false,"accepted",List.of());
        var command=new Prepare("fictional-key-"+suffix,1,Stage.AGENT_ANALYSIS,LocalDate.of(2026,1,1),null,List.of(),List.of(evidence),List.of(),true,"a".repeat(64),ctx);var provider=new GenerationJdbcStore(fixture.source,fixture.clock,"fictional-owner",owner,command);
        new GenerationFlowService(fixture.writes,provider,(stage,snapshot,hash)->"{\"provider\":\"fictional\",\"model\":\"fictional\",\"input_hash\":\""+hash+"\",\"messages\":[{\"role\":\"user\",\"content\":\"Fictional material\"}],\"response_format\":{},\"parameters\":{},\"schema_version\":\"1\",\"prompt_version\":\"1\"}",fixture.clock,()->true).prepare(command,new SharedWriteExecutor.ActionContext("fictional-freeze-"+suffix,owner,"a".repeat(64)));
        String body="{\"title\":\"Fictional dependent\",\"sections\":[],\"citation_ids\":[\"fictional-citation\"],\"category\":\"agent\",\"entity_id\":\""+entity+"\"}";
        return fixture.writes.execute(fixture.action("fictional-create-"+suffix),k->null,a->{new GeneratedContentService(new JdbcGeneratedContents(fixture.source),fixture.clock).write(new GeneratedContentService.Write("agent",id,null,owner,body));var row=base.contents.reviewSnapshot("agent",id).orElseThrow();var version=new ContentVersionKey(row.kind(),row.id(),row.bodyRevision(),HexFormat.of().formatHex(row.bodyHashV1()),row.inputJobId());audit.archiveCurrent(version);return CanonicalJson.parse(JdbcFrozenContentVersions.version(version));});
    }
    @Test void actualEvidenceInvalidationClosesPublishedContentAndReversalNeedsNewReview(){publish();var result=invalidate(base.article(),0,"fictional-invalidate");var publicReads=new ContentReadService(new JdbcContentReads(fixture.source),fixture.tx,new ReviewPublicationService(fixture.writes,new ReviewPublicationJdbcStore(null,base.writer,base.contents,audit,base.versions,base.ledger)));assertTrue(publicReads.published("report","fictional-report").isEmpty());assertTrue(drain("fictional-step-")>=1);assertEquals("withdrawn",base.contents.reviewSnapshot("report","fictional-report").orElseThrow().state());service.change(base.command(base.article(),1,Action.REVERSE_INVALIDATION,result.dispositionId()),fixture.action("fictional-reverse"));assertTrue(publicReads.published("report","fictional-report").isEmpty());review("report","fictional-report","approve","fictional-reapprove");review("report","fictional-report","publish","fictional-republish");assertTrue(publicReads.published("report","fictional-report").isPresent());}
    @Test void delayedOldInvalidationCannotWithdrawReapprovedQualification(){publish();var invalid=invalidate(base.article(),0,"fictional-invalidate");service.change(base.command(base.article(),1,Action.REVERSE_INVALIDATION,invalid.dispositionId()),fixture.action("fictional-reverse"));review("report","fictional-report","approve","fictional-new-approve");review("report","fictional-report","publish","fictional-new-publish");var current=base.contents.reviewSnapshot("report","fictional-report").orElseThrow();drain("fictional-late-");assertEquals("published",base.contents.reviewSnapshot("report","fictional-report").orElseThrow().state());assertEquals(current.revision(),base.contents.reviewSnapshot("report","fictional-report").orElseThrow().revision());}
    @Test void stablePagesCover101FrozenOwnersAndCompletedQueueNeverReenqueuesAfterRestart(){for(int n=0;n<101;n++)seed(String.format("%03d",n),List.of(base.article()));var result=invalidate(base.article(),0,"fictional-invalidate");assertTrue(service.propagateNext(fixture.action("fictional-first-page")));restart(null);int rest=drain("fictional-rest-");assertTrue(rest>=102);assertEquals(103,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent' AND task_type='validity_propagation' AND state='completed'",Integer.class));fixture.writes.execute(fixture.action("fictional-enqueue-duplicate"),k->null,a->{store.enqueue(result.dispositionId(),base.article());return true;});assertFalse(service.propagateNext(fixture.action("fictional-completed-step")));assertEquals(103,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE task_type='validity_propagation'",Integer.class));}
    @Test void oldMiddleVersionTraversesDownstreamAfterBodyReplacementAndStaleCasSkips(){var old=seed("middle",List.of(base.article()));var child=seed("child",List.of(old));review("agent","fictional-agent-child","approve","fictional-child-approve");review("agent","fictional-agent-child","publish","fictional-child-publish");var middle=base.contents.reviewSnapshot("agent","fictional-agent-middle").orElseThrow();String replacement=middle.bodyJson().replace("Fictional dependent","Fictional replaced");fixture.writes.execute(fixture.action("fictional-replace-middle"),k->null,a->{base.writer.edit(middle,replacement,HexFormat.of().parseHex(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(replacement))));return true;});invalidate(base.article(),0,"fictional-invalidate");drain("fictional-chain-");assertEquals(2,base.contents.reviewSnapshot("agent","fictional-agent-middle").orElseThrow().bodyRevision());assertEquals("draft",base.contents.reviewSnapshot("agent","fictional-agent-middle").orElseThrow().state());assertEquals("withdrawn",base.contents.reviewSnapshot("agent","fictional-agent-child").orElseThrow().state());assertEquals(0,base.ledger.validity(child).revision());}
    @Test void commitAckLossAndUnknownStepReplayNeverAdvanceOrWithdrawTwice(){publish();fixture.tx.ackLost=true;var result=invalidate(base.article(),0,"fictional-invalidate");assertTrue(result.replayed());assertEquals(result.dispositionId(),invalidate(base.article(),0,"fictional-invalidate").dispositionId());fixture.tx.ackLost=true;assertTrue(service.propagateNext(fixture.action("fictional-step-unknown")));restart(null);assertTrue(service.propagateNext(fixture.action("fictional-step-unknown")));assertEquals(1,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='validity_step'",Integer.class));drain("fictional-next-");var row=base.contents.reviewSnapshot("report","fictional-report").orElseThrow();assertEquals(4,row.revision());}
    @Test void displayWithdrawalHasPermanentCommandReceiptAndNoConclusionInvalidation(){publish();var target=base.content();restart(new VersionValidityJdbcStore.DisplayCommand(target,3,"Fictional display arrangement"));fixture.tx.ackLost=true;service.displayAdjustment(target,fixture.action("fictional-display"));restart(new VersionValidityJdbcStore.DisplayCommand(target,3,"Fictional display arrangement"));service.displayAdjustment(target,fixture.action("fictional-display"));assertEquals(4,base.contents.reviewSnapshot("report","fictional-report").orElseThrow().revision());assertEquals(new Validity(0,true,Set.of()),base.ledger.validity(target));assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE task_type='validity_propagation'",Integer.class));restart(new VersionValidityJdbcStore.DisplayCommand(target,3,"Fictional different arrangement"));assertThrows(IllegalStateException.class,()->service.displayAdjustment(target,fixture.action("fictional-display")));}
    @Test void queueFailureRollsBackLedgerAndPhysicalValidityAndOldBatchCannotOverrideNewReview(){fixture.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_queue_failure CHECK(task_type IS NULL OR task_type<>'validity_propagation')");assertThrows(RuntimeException.class,()->invalidate(base.article(),0,"fictional-failed-invalidate"));assertEquals(new Validity(0,true,Set.of()),base.ledger.validity(base.article()));}
    @Test void cyclicFrozenReferencesKeepCompletedIdentityAndTerminate(){String body="{\"title\":\"Fictional dependent\",\"sections\":[],\"citation_ids\":[\"fictional-citation\"],\"category\":\"agent\",\"entity_id\":\"fictional-entity-cycle\"}";var cycle=CanonicalJson.parse(JdbcFrozenContentVersions.version(new ContentVersionKey("agent","fictional-agent-cycle",1,CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(body)),"fictional-owner-cycle")));assertEquals(cycle,seed("cycle",List.of(base.article(),cycle)));invalidate(base.article(),0,"fictional-cycle-invalidate");assertTrue(drain("fictional-cycle-step-")<10);assertEquals(3,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE task_type='validity_propagation' AND state='completed'",Integer.class));}
    @Test void oldCapturedBatchAndFailedCurrentClosureLeaveNewOrOriginalQualification(){publish();var original=base.contents.reviewSnapshot("report","fictional-report").orElseThrow();var old=new Dependent(base.content(),original.revision(),original.inputJobId(),HexFormat.of().formatHex(original.reviewStampHash()));var invalid=invalidate(base.article(),0,"fictional-old-invalidation");service.change(base.command(base.article(),1,Action.REVERSE_INVALIDATION,invalid.dispositionId()),fixture.action("fictional-old-reversal"));review("report","fictional-report","approve","fictional-after-reversal");fixture.writes.execute(fixture.action("fictional-old-cas"),k->null,a->{assertFalse(store.blockIfCurrent(old,invalid.dispositionId()));return true;});assertEquals("approved",base.contents.reviewSnapshot("report","fictional-report").orElseThrow().state());var forbidden=JsonMapper.shared().createObjectNode();forbidden.put("schema_version","validity-work-v1");forbidden.put("disposition_id",JdbcFrozenInputs.stableId("validity","fictional-current-failure"));forbidden.set("target",base.content());String forbiddenHash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,forbidden);fixture.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_current_queue_failure CHECK(task_type IS NULL OR task_type<>'validity_propagation' OR input_hash<>UNHEX('"+forbiddenHash+"'))");assertThrows(RuntimeException.class,()->invalidate(base.content(),0,"fictional-current-failure"));assertEquals("approved",base.contents.reviewSnapshot("report","fictional-report").orElseThrow().state());assertEquals(new Validity(0,true,Set.of()),base.ledger.validity(base.content()));}
}
